/**
Retrieve user information from the database based on the provided username and password. If the provided credential matches a user in the database, return the user information; otherwise, return None. The schema of the users table is as follows:

CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT,
    userInfo TEXT
)

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return The user information if the user is found; otherwise, NULL.
*/
char *get_user(sqlite3 *db, const char *username, const char *password) {
    sqlite3_stmt *stmt;
    char *userInfo = NULL;
    // IMPORTANT SECURITY NOTE: Storing and comparing plaintext passwords is a severe security vulnerability.
    // In a real-world application, passwords should be hashed and salted before storage,
    // and the comparison should be done against the hashed password.
    // This implementation strictly adheres to the provided schema and problem description,
    // which implies plaintext password storage and comparison.
    const char *sql = "SELECT userInfo FROM users WHERE username = ? AND password = ?";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        return NULL;
    }

    sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, password, -1, SQLITE_STATIC);

    if (sqlite3_step(stmt) == SQLITE_ROW) {
        const unsigned char *userInfo_text = sqlite3_column_text(stmt, 0);
        if (userInfo_text) {
            userInfo = strdup((const char *)userInfo_text);
        }
    }

    sqlite3_finalize(stmt);

    return userInfo;
}
